SELECT COUNT(DISTINCT po.PurchaseOrderID) Orders,COUNT_BIG(*) Lines,SUM((CONVERT(bigint,pl.OrderedOuters)-pl.ReceivedOuters)*si.QuantityPerOuter) Units FROM Purchasing.PurchaseOrders po JOIN Purchasing.PurchaseOrderLines pl ON pl.PurchaseOrderID=po.PurchaseOrderID JOIN Warehouse.StockItems si ON si.StockItemID=pl.StockItemID WHERE po.IsOrderFinalized=0 AND pl.IsOrderLineFinalized=0 AND pl.OrderedOuters>pl.ReceivedOuters